'use strict';

// MODULES //

var isnan = require( '@stdlib/assert/is-nan' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var round = require( '@stdlib/math/base/special/round' );
var gamma = require( '@stdlib/math/base/special/gamma' );
var pow = require( '@stdlib/math/base/special/pow' );
var abs = require( '@stdlib/math/base/special/abs' );
var isNonPositiveInteger = require( './utils.js' ).isNonPositiveInteger;
var isInteger = require( './utils.js' ).isInteger;
var hys2f1 = require( './hys2f1.js' );
var hyt2f1 = require( './hyt2f1.js' );


// VARIABLES //

var ETHRESH = 1.0e-12;


// MAIN //

/**
* Evaluates the Gaussian hypergeometric function.
*
* @param {number} a - input value
* @param {number} b - input value
* @param {number} c - input value
* @param {number} x - input value
* @returns {number} function value
*
* @example
* var v = hyp2f1( 1.0, 1.0, 1.0, 0.0 );
* // returns 1.0
*
* @example
* var v = hyp2f1( 10.0, 7.4, -1.8, -0.99 );
* // returns ~0.423
*
* @example
* var v = hyp2f1( 10.0, 1.0, -1.8, -0.99 );
* // returns ~-0.875
*
* @example
* var v = hyp2f1( 2.0, 3.0, 5.0, 0.99 );
* // returns ~27.699
*
* @example
* var v = hyp2f1( 3.0, 4.0, 7.0, 1.0 );
* // returns Infinity
*
* @example
* var v = hyp2f1( NaN, 3.0, 2.0, 0.5 );
* // returns NaN
*
* @example
* var v = hyp2f1( 1.0, NaN, 2.0, 0.5 );
* // returns NaN
*/
function hyp2f1( a, b, c, x ) {
	var negIntCaOrCb;
	var negIntC;
	var negIntB;
	var negIntA;
	var isIntD;
	var aid;
	var err;
	var ax;
	var d2;
	var d1;
	var id;
	var ic;
	var ia;
	var ib;
	var t1;
	var q;
	var r;
	var p;
	var e;
	var s;
	var d;
	var y;
	var i;

	err = 0.0;
	ax = abs( x );
	ia = round( a );
	ib = round( b );
	id = round( d );
	ic = round( c );
	s = 1.0 - x;
	d = c - a - b;
	negIntA = isNonPositiveInteger( a );
	negIntB = isNonPositiveInteger( b );
	negIntC = isNonPositiveInteger( c );
	isIntD = isInteger( d );
	t1 = abs( b - a );

	if ( isnan( a ) || isnan( b ) || isnan( c ) || isnan( x ) ) {
		return NaN;
	}

	if ( x === 0.0 ) {
		return 1.0;
	}

	if ( ( a === 0.0 || b === 0.0 ) && c !== 0.0 ) {
		return 1.0;
	}

	if ( d <= -1.0 && !( !isIntD && s < 0.0 ) && !( negIntA || negIntB ) ) {
		return pow( s, d ) * hyp2f1( c - a, c - b, c, x );
	}

	if ( d <= 0.0 && x === 1.0 && !( negIntA || negIntB ) ) {
		return PINF;
	}

	if ( ax < 1.0 || x === -1.0 ) {
		if ( b === c ) {
			return pow( s, -a );
		}
		if ( a === c ) {
			return pow( s, -b );
		}
	}

	if ( negIntC ) {
		if ( negIntA && ( ia > ic ) ) {
			y = hyt2f1( a, b, c, x, err );
			return y.value;
		}
		if ( negIntB && ( ib > ic ) ) {
			y = hyt2f1( a, b, c, x, err );
			return y.value;
		}
		return PINF;
	}

	if ( negIntA || negIntB )	{
		y = hyt2f1( a, b, c, x, err );
		return y.value;
	}

	if ( x < -2.0 && !isInteger( t1 ) ) {
		p = hyp2f1( a, 1.0 - c + a, 1.0 - b + a, 1.0 / x );
		q = hyp2f1( b, 1.0 - c + b, 1.0 - a + b, 1.0 / x );
		p *= pow( -x, -a );
		q *= pow( -x, -b );
		t1 = gamma( c );
		s = t1 * gamma( b - a ) / ( gamma( b ) * gamma( c - a ) );
		y = t1 * gamma( a - b ) / ( gamma( a ) * gamma( c - b ) );
		return ( s * p ) + ( y * q );
	}
	if ( x < -1.0 ) {
		if ( abs( a ) < abs( b ) ) {
			return pow( s, -a ) * hyp2f1( a, c - b, c, x / ( x - 1.0 ) );
		}
		return pow( s, -b ) * hyp2f1( b, c - a, c, x / ( x - 1.0 ) );
	}

	if ( ax > 1.0 ) {
		return PINF;
	}

	p = c - a;
	r = c - b;
	negIntCaOrCb = isNonPositiveInteger( p ) || isNonPositiveInteger( r );
	if ( ax === 1.0 ) {
		if ( x > 0.0 ) {
			if ( negIntCaOrCb ) {
				if ( d >= 0.0 ) {
					y = hys2f1( c - a, c - b, c, x, err );
					return pow( s, d ) * y.value;
				}
				return PINF;
			}
			if ( d <= 0.0 ) {
				return PINF;
			}
			return gamma( c ) * gamma( d ) / ( gamma( p ) * gamma( r ) );
		}
		if ( d <= -1.0 ) {
			return PINF;
		}
	}

	if ( d < 0.0 ) {
		y = hyt2f1( a, b, c, x, err );
		if ( y.error < ETHRESH ) {
			return y.value;
		}
		y = y.value;
		err = 0.0;
		aid = 2.0 - id;
		e = c + aid;
		d2 = hyp2f1( a, b, e, x );
		d1 = hyp2f1( a, b, e + 1.0, x );
		q = a + b + 1.0;
		for ( i = 0; i < aid; i++ ) {
			r = e - 1.0;

			// eslint-disable-next-line max-len
			y = (((e * (r - (((2.0 * e) - q) * x))) * d2) + (((e - a) * (e - b) * x) * d1)) / (e * r * s);
			e = r;
			d1 = d2;
			d2 = y;
		}
		return y;
	}

	if ( negIntCaOrCb ) {
		y = hys2f1( c - a, c - b, c, x, err );
		return pow( s, d ) * y.value;
	}

	y = hyt2f1( a, b, c, x, err );
	return y.value;
}


// EXPORTS //

module.exports = hyp2f1;
